import { test, expect } from '@playwright/test';

test.describe('API Response Handling', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/your-page-url'); // Replace with your actual page URL
  });

  test('should display "No results found" message when API returns an empty list', async ({ page }) => {
    // Mock the API response to return an empty list
    await page.route('**/your-api-endpoint', (route) => {
      route.fulfill({
        status: 200,
        contentType: 'application/json',
        body: JSON.stringify([]),
      });
    });

    // Trigger the API call
    await page.click(getByRole('button', { name: /fetch data/i })); // Replace with your actual button role and name

    // Assert that the "No results found" message is displayed
    const noResultsMessage = await page.getByText('No results found');
    await expect(noResultsMessage).toBeVisible();
  });

  test('should not display "No results found" message when API returns data', async ({ page }) => {
    // Mock the API response to return a non-empty list
    await page.route('**/your-api-endpoint', (route) => {
      route.fulfill({
        status: 200,
        contentType: 'application/json',
        body: JSON.stringify([{ id: 1, name: 'Item 1' }]),
      });
    });

    // Trigger the API call
    await page.click(getByRole('button', { name: /fetch data/i })); // Replace with your actual button role and name

    // Assert that the "No results found" message is not displayed
    const noResultsMessage = await page.getByText('No results found');
    await expect(noResultsMessage).not.toBeVisible();
  });
});
